theme.rawCss:
@property --ui-button-wave-r {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}
@keyframes ui-button-wave-mantine {
  0% { background-image: radial-gradient(circle at 50% 50%, var(--ui-button-wave-color) 0 var(--ui-button-wave-r, 0%), transparent calc(var(--ui-button-wave-r, 0%) + 1px)); opacity: var(--ui-button-wave-opacity, 0.35); }
  100% { --ui-button-wave-r: 130%; background-image: radial-gradient(circle at 50% 50%, var(--ui-button-wave-color) 0 var(--ui-button-wave-r, 0%), transparent calc(var(--ui-button-wave-r, 0%) + 1px)); opacity: 0; }
}
